mapper.select:
select 

    , hit.display_name as matched_attachment,
      substring(body.content,greatest(locate(#{keyword},body.content)-30,1),char_length(#{keyword})+60) as attachment_excerpt

from arc_archive a left join arc_category c on c.category_id=a.category_id

    left join arc_file hit on hit.file_id=(
        select min(f.file_id)
        from arc_file f join arc_file_text t on t.file_id=f.file_id and t.source_sha256=f.sha256
        where f.archive_id=a.archive_id and locate(#{keyword},t.content) > 0
    )
    left join arc_file_text body on body.file_id=hit.file_id and body.source_sha256=hit.sha256


    a.del_flag='0'
    and a.create_by=#{ownerName}
    and a.archive_code like concat('%',#{archiveCode},'%')
    and a.title like concat('%',#{title},'%')

        and (locate(#{keyword}, a.archive_code) > 0 or locate(#{keyword}, a.title) > 0
            or locate(#{keyword}, a.summary) > 0
            or hit.file_id is not null)

    and a.category_id=#{categoryId}
    and a.secret_level=#{secretLevel}
    and a.archive_status=#{archiveStatus}
    and a.forming_date >=#{dateFrom}
    and a.forming_date <=#{dateTo}
    and a.category_id in
        #{categoryId}

    and a.secret_level <=#{maxSecretLevel}


    order by a.archive_code
    order by a.title
    order by a.forming_date
    order by a.create_time

ascdesc,a.archive_id desc

mapper.update:
update arc_archive set archive_status='SUBMITTED',version=version+1,update_by=#{updateBy},update_time=now()
where archive_id=#{archiveId} and version=#{version} and archive_status='DRAFT' and del_flag='0'
and create_by=#{ownerName}

update arc_archive
secret_level=#{secretLevel}, retention_code=#{retentionCode},retention_name=#{retentionName}, version=version+1,update_by=#{updateBy},update_time=now()
where archive_id=#{archiveId} and version=#{version} and archive_status='DRAFT' and del_flag='0' and create_by=#{ownerName}

update arc_archive set del_flag='1',version=version+1,update_by=#{updateBy},update_time=now()
where archive_id=#{archiveId} and version=#{version} and archive_status='DRAFT' and del_flag='0'
and create_by=#{ownerName}

mapper.select:
select

    a.secret_level
    a.category_id
    a.archive_status

statisticKey,count(*) total from arc_archive a

    a.del_flag='0'
    and a.create_by=#{ownerName}
    and a.archive_code like concat('%',#{archiveCode},'%')
    and a.title like concat('%',#{title},'%')

        and (locate(#{keyword}, a.archive_code) > 0 or locate(#{keyword}, a.title) > 0
            or locate(#{keyword}, a.summary) > 0

                or exists (
                    select 1 from arc_file f join arc_file_text t on t.file_id=f.file_id and t.source_sha256=f.sha256
                    where f.archive_id=a.archive_id and f.revoked=0 and locate(#{keyword},t.content) > 0
                )
            )

    and a.category_id=#{categoryId}
    and a.secret_level=#{secretLevel}
    and a.archive_status=#{archiveStatus}
    and a.forming_date >=#{dateFrom}
    and a.forming_date <=#{dateTo}
    and a.category_id in
        #{categoryId}

    and a.secret_level <=#{maxSecretLevel}


    group by a.secret_level order by a.secret_level
    group by a.category_id order by a.category_id
    group by a.archive_status order by a.archive_status
